import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import toast from 'react-hot-toast';
import { uploadPartyEmails } from '../services/api';
import { Upload, Lock, FileSpreadsheet, AlertTriangle, CheckCircle } from 'lucide-react';

export default function PartyEmailUpload() {
  const [password, setPassword] = useState('');
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  const onDrop = useCallback((accepted) => {
    if (accepted.length) setFile(accepted[0]);
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'] },
    maxFiles: 1,
  });

  const handleUpload = async () => {
    if (!file) return toast.error('Please select an Excel file');
    if (!password) return toast.error('Please enter the upload password');
    setLoading(true);
    setResult(null);
    try {
      const res = await uploadPartyEmails(file, password);
      setResult(res.data);
      toast.success(res.data.message);
      setFile(null);
      setPassword('');
    } catch (err) {
      const msg = err.response?.data?.message || 'Upload failed';
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="upload-section">
      <div className="input-group">
        <Lock size={16} className="input-icon" />
        <input
          type="password"
          placeholder="Enter upload password"
          value={password}
          onChange={e => setPassword(e.target.value)}
        />
      </div>

      <div
        {...getRootProps()}
        className={`dropzone ${isDragActive ? 'active' : ''} ${file ? 'has-file' : ''}`}
      >
        <input {...getInputProps()} />
        {file ? (
          <div className="dropzone-file">
            <FileSpreadsheet size={32} />
            <span>{file.name}</span>
            <small>{(file.size / 1024).toFixed(1)} KB</small>
          </div>
        ) : (
          <div className="dropzone-empty">
            <Upload size={32} />
            <p>{isDragActive ? 'Drop file here…' : 'Drag & drop Party Email Excel, or click to browse'}</p>
            <small>Requires columns: Party Code, Party Name, Email, CC</small>
          </div>
        )}
      </div>

      <button
        className="btn btn-primary"
        onClick={handleUpload}
        disabled={loading || !file || !password}
      >
        {loading ? <span className="spinner-sm" /> : <Upload size={16} />}
        {loading ? 'Uploading…' : 'Upload Email List'}
      </button>

      {result && (
        <div className="upload-result">
          <div className="alert alert-success">
            <CheckCircle size={16} />
            {result.message}
          </div>
          {result.missingEmails?.length > 0 && (
            <div className="alert alert-warning">
              <AlertTriangle size={16} />
              <div>
                <strong>Vendors with no email address:</strong>
                <ul>
                  {result.missingEmails.map((m, i) => <li key={i}>{m}</li>)}
                </ul>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
